#!/usr/bin/env python3
"""DEPLOY VERSION 6 — writes all app files. Run: bash deploy.sh"""
import base64, json, zlib
from pathlib import Path
_BUNDLE = ""
def main():
    print("install_app.py v6")
    for rel, text in json.loads(zlib.decompress(base64.b64decode(_BUNDLE))).items():
        p = Path(rel); p.parent.mkdir(parents=True, exist_ok=True); p.write_text(text); print("  Wrote", rel)
    print("Done.")
if __name__ == "__main__": main()